    <title>AMC | Motociclismo de Cochabamba</title>
    <style>
        :root { --ink:#11151a; --muted:#65707c; --paper:#f4f5f2; --line:#dfe3e5; --accent:#e0441e; --accent-dark:#a92d14; }
        * { box-sizing:border-box; } body { margin:0; color:var(--ink); background:var(--paper); font-family:"Trebuchet MS","Segoe UI",sans-serif; } a { color:inherit; text-decoration:none; }
        .amc-shell { overflow:hidden; } .amc-nav { position:absolute; z-index:2; inset:0 0 auto; display:flex; align-items:center; justify-content:space-between; gap:2rem; padding:1.35rem clamp(1rem,5vw,5rem); color:#fff; }
