        .amc-button-outline { border-color:rgba(255,255,255,.55); color:#fff; } .amc-button-outline:hover { background:#fff; color:var(--ink); } .amc-button-accent { background:var(--accent); color:#fff; } .amc-button-accent:hover { background:var(--accent-dark); color:#fff; } .amc-button-dark { background:var(--ink); color:#fff; } .amc-button-light { border-color:var(--line); color:var(--ink); }
