        .amc-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:1rem; } .amc-card { display:flex; flex-direction:column; min-width:0; padding:1.35rem; border:1px solid var(--line); border-radius:8px; background:#fff; box-shadow:0 12px 30px rgba(20,27,32,.06); } .amc-card h3 { margin:.75rem 0 .45rem; font-size:1.2rem; } .amc-meta { color:var(--muted); font-size:.8rem; line-height:1.8; } .amc-summary { flex:1; margin:.8rem 0 1.1rem; color:#4e5963; font-size:.9rem; line-height:1.55; } .amc-badge { display:inline-block; align-self:flex-start; padding:.28rem .55rem; border-radius:3px; background:#fff0eb; color:var(--accent-dark); font-size:.67rem; font-weight:900; letter-spacing:.06em; text-transform:uppercase; } .amc-tags { margin-top:.55rem; color:var(--accent-dark); font-size:.74rem; font-weight:700; } .amc-card-actions { display:flex; flex-wrap:wrap; gap:.5rem; } .amc-card-actions .amc-button { min-height:36px; padding:.45rem .7rem; }
        .amc-feature { display:grid; grid-template-columns:minmax(0,1.4fr) minmax(260px,.8fr); gap:2rem; align-items:center; padding:2rem; border-radius:8px; background:var(--ink); color:#fff; } .amc-feature h2 { margin:.75rem 0; font-size:clamp(1.8rem,4vw,3.4rem); } .amc-feature .amc-meta,.amc-feature .amc-summary { color:#bbc2c7; } .amc-feature-aside { padding:1.25rem; border-left:3px solid var(--accent); background:rgba(255,255,255,.06); }
