        .amc-footer { padding:2.5rem clamp(1rem,5vw,5rem); background:var(--ink); color:#fff; } .amc-footer-inner { display:flex; justify-content:space-between; gap:2rem; max-width:1220px; margin:auto; } .amc-footer p,.amc-footer small { color:#aab2b8; } .amc-footer-links { display:flex; flex-wrap:wrap; gap:1rem; color:#d9dddf; font-size:.8rem; } .amc-empty { padding:2rem; border:1px dashed #c7ced2; border-radius:8px; color:var(--muted); text-align:center; }
        @media (max-width:800px) { .amc-nav { flex-wrap:wrap; gap:.7rem; } .amc-menu-toggle { display:block; margin-left:auto; } .amc-links { display:none; order:3; flex:1 0 100%; flex-direction:column; align-items:stretch; gap:0; padding:.65rem 0; border-top:1px solid rgba(255,255,255,.2); } .amc-links.is-open { display:flex; } .amc-links a { padding:.6rem 0; } .amc-actions { gap:.4rem; } .amc-feature,.amc-grid { grid-template-columns:1fr; } .amc-stat-grid { grid-template-columns:repeat(2,1fr); } .amc-stat:nth-child(2) { border-right:0; } .amc-stat:nth-child(-n+2) { border-bottom:1px solid var(--line); } .amc-footer-inner { flex-direction:column; } } @media (max-width:480px) { .amc-nav { padding:1rem; } .amc-brand { font-size:1.1rem; } .amc-actions { max-width:calc(100% - 3.5rem); } .amc-actions .amc-button { min-height:36px; padding-inline:.55rem; font-size:.66rem; } .amc-hero { min-height:590px; padding-inline:1rem; } h1 { font-size:3.1rem; } }
